// jwt — HS256 JWT sign/verify
// Algo: HS256

fn b64url::(data) {
    let s = @base64(@bytes(data));
    let out = "";
    for i in @range(0, @len(s)) {
        let c = @str_char_at(s, i);
        if (c == "+") { out += "-"; }
        else if (c == "/") { out += "_"; }
        else if (c == "=") { continue; }
        else { out += c; }
    }
    return out;
}

fn b64url_decode::(s) {
    let padded = s;
    while (@len(padded) % 4 != 0) { padded += "="; }
    let std = "";
    for i in @range(0, @len(padded)) {
        let c = @str_char_at(padded, i);
        if (c == "-") { std += "+"; }
        else if (c == "_") { std += "/"; }
        else { std += c; }
    }
    return @base64_decode(std);
}

fn jwt_sign::(payload, secret) {
    let header = {"alg": "HS256", "typ": "JWT"};
    let h = b64url(@bytes(@json_encode(header)));
    let p = b64url(@bytes(@json_encode(payload)));
    let signing_input = h + "." + p;
    let sig = @hmac_sha256(@bytes(secret), @bytes(signing_input));
    return signing_input + "." + b64url(sig);
}

fn jwt_verify::(token, secret) {
    let parts = @split(token, ".");
    if (@len(parts) != 3) { return {"ok": false, "error": "malformed"}; }
    let signing_input = parts[0] + "." + parts[1];
    let expected = @hmac_sha256(@bytes(secret), @bytes(signing_input));
    let actual = b64url_decode(parts[2]);
    if (!@crypto_equal(@bytes_hex(actual), @bytes_hex(expected))) {
        return {"ok": false, "error": "bad signature"};
    }
    let payload = @json_decode(@mem_to_string(@mem_from_bytes(b64url_decode(parts[1]))));
    if (@map_has_key(payload, "exp")) {
        if (payload["exp"] < @time_ms() / 1000) {
            return {"ok": false, "error": "expired"};
        }
    }
    return {"ok": true, "payload": payload};
}

fn jwt_exp::(payload, seconds) {
    payload["exp"] = @time_ms() / 1000 + seconds;
    payload["iat"] = @time_ms() / 1000;
    return payload;
}

fn version::() { return "1.0.0"; }
